INSERT INTO service_questions(service_id,label,type,options,is_required,position)
SELECT s.id,'Qual é o tipo de atendimento?','select','["Presencial","Online","A combinar"]',true,1 FROM services s WHERE NOT EXISTS(SELECT 1 FROM service_questions q WHERE q.service_id=s.id);
INSERT INTO lead_pricing_rules(service_id,coin_cost) SELECT s.id,8 FROM services s WHERE NOT EXISTS(SELECT 1 FROM lead_pricing_rules p WHERE p.service_id=s.id);
